<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\QuestionLearning;
use App\Domain\QuestionLearning\Repository\CompletedAttemptLearningSignalReaderInterface;use App\Domain\QuestionLearning\ValueObject\CompletedAttemptLearningSignal;use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionRecord;use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionTaxonomySubjectRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineCompletedAttemptLearningSignalReader implements CompletedAttemptLearningSignalReaderInterface { public function __construct(private readonly EntityManagerInterface $entityManager) {} public function read(string $questionId, string $selectedOptionId, int $elapsedSeconds, string $origin): ?CompletedAttemptLearningSignal { $question=$this->entityManager->find(QuestionRecord::class,$questionId);if(!$question instanceof QuestionRecord||$question->correctOptionId===null)return null;$subjects=array_map(static fn(QuestionTaxonomySubjectRecord $record):string=>$record->taxonomySubjectId,$this->entityManager->createQueryBuilder()->select('subject')->from(QuestionTaxonomySubjectRecord::class,'subject')->where('subject.questionId=:questionId')->setParameter('questionId',$questionId)->getQuery()->getResult());return new CompletedAttemptLearningSignal($questionId,$selectedOptionId,$question->correctOptionId===$selectedOptionId,$elapsedSeconds,$origin,$subjects); } public function taxonomySubjectIdsForQuestion(string $questionId): array { return array_map(static fn(QuestionTaxonomySubjectRecord $record): string => $record->taxonomySubjectId, $this->entityManager->createQueryBuilder()->select('subject')->from(QuestionTaxonomySubjectRecord::class,'subject')->where('subject.questionId = :questionId')->setParameter('questionId',$questionId)->getQuery()->getResult()); } }
